// ===================== PENGATURAN — boleh diubah tanpa coding lain =====================
// Instruksi tambahan untuk AI (ditambahkan ke prompt bawaan NEXBILL). Contoh: promo yang SEDANG
// berlaku, gaya bahasa, atau hal yang tidak boleh dijanjikan. Kosongkan bila tidak ada.
const INSTRUKSI_TAMBAHAN_AI = ``;

// FAQ tanpa AI: bila pesan prospek mengandung salah satu kata kunci, jawaban ini langsung dikirim
// (cepat & gratis). Tulis hanya fakta yang benar. {daftar} {harga} {katalog} diisi otomatis.
const FAQ = [
  {
    kata: ["iphone", "ios"],
    jawab: "Dashboard NEXBILL bisa dibuka di browser iPhone 🙂 Khusus cetak struk ke printer Bluetooth, saat ini hanya dari HP Android (aplikasi NEXBILL atau Chrome Android).",
  },
  {
    kata: ["kartu kredit"],
    jawab: "Coba gratisnya tanpa kartu kredit, Kak 🙂 Daftar di {daftar}",
  },
];
// =======================================================================================

const p = $input.first().json.body || {};
const m = p.message || {};
const t = p.templates || {};
const links = (p.facts && p.facts.links) || {};
const teks = String(m.text || "").toLowerCase();
const isi = (s) => String(s).replace("{daftar}", links.daftar || "").replace("{harga}", links.harga || "").replace("{katalog}", links.katalog || "");

let jawab = null;
if (m.mediaOnly) jawab = { reply: t.mediaOnly, menu: true };
else if (m.menuChoice === "price") jawab = { reply: t.price, menu: true, intent: "question" };
else if (m.menuChoice === "features") jawab = { reply: t.features, menu: true, intent: "question" };
else if (m.menuChoice === "trial") jawab = { reply: t.trial, menu: true, intent: "subscribe" };
else if (m.menuChoice === "human") jawab = { reply: t.handoff, intent: "human", handoff: true };
else if (m.menuChoice === "customer") jawab = { reply: null, intent: "support" };
else if (m.isGreeting) jawab = { reply: t.welcome, menu: true };
else {
  const faq = FAQ.find((f) => f.kata.some((k) => teks.includes(k.toLowerCase())));
  if (faq) jawab = { reply: isi(faq.jawab), intent: "question" };
}

if (jawab) {
  return [{ json: { route: "tetap", response: { reply: null, intent: "other", handoff: false, menu: false, extracted: {}, ...jawab } } }];
}

// Selain itu → tanya Claude dengan prompt bawaan NEXBILL (harga live + tabel fitur + aturan).
const lead = p.lead || {};
const sistem = [
  (p.ai && p.ai.systemPrompt) || "",
  INSTRUKSI_TAMBAHAN_AI ? `\nINSTRUKSI TAMBAHAN DARI ADMIN NEXBILL:\n${INSTRUKSI_TAMBAHAN_AI}` : "",
  `\nData lead saat ini: nama="${lead.name || "?"}", kota=${lead.city || "?"}, unit=${lead.unitCount || "?"}, billing sekarang=${lead.currentBilling || "?"}, kontak=${lead.contactName || "?"}. Bahasa pelanggan kemungkinan: ${m.lang || "id"}.`,
].join("");
const riwayat = Array.isArray(p.history) && p.history.length ? p.history : [{ role: "user", content: String(m.text || "") }];

return [
  {
    json: {
      route: "ai",
      anthropicRequest: { model: (p.ai && p.ai.model) || "claude-haiku-5-5", max_tokens: 700, system: sistem, messages: riwayat },
    },
  },
];

// Jawaban Claude → format yang dipahami bot NEXBILL. Bila AI gagal/kosong, kirim {} supaya bot
// otomatis memakai otak bawaannya (prospek tetap dibalas).
const res = $input.first().json || {};
const teks = (res.content || []).filter((c) => c.type === "text").map((c) => c.text).join("\n");
const a = teks.indexOf("{");
const b = teks.lastIndexOf("}");
let o = null;
try {
  o = a >= 0 && b > a ? JSON.parse(teks.slice(a, b + 1)) : null;
} catch (e) {
  o = null;
}
if (!o || typeof o.reply !== "string" || !o.reply.trim()) return [{ json: { response: {} } }];
return [
  {
    json: {
      response: { reply: o.reply, intent: o.intent || "question", handoff: o.handoff === true, extracted: o.extracted || {}, menu: false },
    },
  },
];
